{
  "title": "The Rescue of the Crown's Last Heir",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The heroes approach the ruined royal city.",
      "visual_description": "A crumbling stone gatehouse looms under a gray sky, tattered royal banners flutter from broken battlements, and a rusted portcullis is half-raised.",
      "characters": ["Captain Eira", "Lysander the Scholar"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn the heroes of dangers ahead.",
      "visual_description": "A cluster of ragged civilians huddle by a collapsed fountain, pointing with trembling hands toward the city's inner walls.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Town Elder"]
    },
    {
      "scene_number": 3,
      "caption": "The party enters the cursed tower to find a key.",
      "visual_description": "A spiral staircase of black stone winds upward, lit by eerie blue flames that cast no heat, and the walls are covered in shifting runes.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer"]
    },
    {
      "scene_number": 4,
      "caption": "A phantom knight guards the tower's upper chamber.",
      "visual_description": "A translucent armored figure stands before a pedestal holding a golden key, its sword glowing with pale light, and its helm empty of a face.",
      "characters": ["Captain Eira", "Phantom Knight"]
    },
    {
      "scene_number": 5,
      "caption": "The heroes defeat the phantom and claim the key.",
      "visual_description": "Eira's steel clashes with the phantom's blade, Lysander chants a banishing verse, and Mara's healing light stabilizes a wound; the key is seized.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Phantom Knight"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon reach the party from a fugitive knight.",
      "visual_description": "A battered knight in dented armor hides in a collapsed stable, whispering about a great beast that sleeps beneath the palace.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Fugitive Knight"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol ambushes the heroes in a narrow street.",
      "visual_description": "Six soldiers in oxidized bronze armor block the cobblestone lane, their shields bearing the old royal crest, and their swords drawn.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Armored Patrol Soldier 1", "Armored Patrol Soldier 2", "Armored Patrol Soldier 3", "Armored Patrol Soldier 4", "Armored Patrol Soldier 5", "Armored Patrol Soldier 6"]
    },
    {
      "scene_number": 8,
      "caption": "The party outmaneuvers the patrol using a secret alley.",
      "visual_description": "Lysander notices a hidden passage behind a false wall of ivy, and the heroes slip through just as the soldiers round the corner.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer"]
    },
    {
      "scene_number": 9,
      "caption": "They discover the magic door to the prison wing.",
      "visual_description": "A massive door of obsidian with a pulsing violet sigil stands at the end of a torchlit corridor, humming with arcane energy.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer"]
    },
    {
      "scene_number": 10,
      "caption": "Lysander deciphers the riddle to open the magic door.",
      "visual_description": "He traces the sigil with his finger while reading from an ancient tome; the door's runes flare and the stone grinds open.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer"]
    },
    {
      "scene_number": 11,
      "caption": "The prison cell holds the captive heir—Prince Aldric.",
      "visual_description": "A skeletal young man in tattered finery sits on straw, iron chains binding his wrists to the wall, a single ray of light illuminating his face.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric"]
    },
    {
      "scene_number": 12,
      "caption": "Mara tends to the prince's wounds as the chains are broken.",
      "visual_description": "Eira smashes the chains with a hammer, Mara applies a salve to his bruised wrists, and Aldric stands weakly, leaning on Lysander.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric"]
    },
    {
      "scene_number": 13,
      "caption": "A false escape: the dragon awakens beneath the palace.",
      "visual_description": "The floor cracks, revealing a vast cavern below where a red dragon stirs, its eye slitting open, smoke curling from its nostrils.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric", "Dragon"]
    },
    {
      "scene_number": 14,
      "caption": "The heroes lure the dragon into a trap of falling columns.",
      "visual_description": "Eira taunts the beast, leading it under a weakened arch; Lysander triggers a collapse, burying the dragon in rubble.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric", "Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "They race through the crumbling palace to the outer courtyard.",
      "visual_description": "Fires spread, stone pillars fall, and the party sprints through a hall of shattered stained glass, the exit in sight.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric"]
    },
    {
      "scene_number": 16,
      "caption": "The final bridge: a narrow stone span over a chasm.",
      "visual_description": "The bridge is cracked and missing several stones, with a hundred-foot drop into mist below; the far gate is open.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge collapses as they cross, but all make it.",
      "visual_description": "Eira leaps last, the stone crumbling behind her; Mara catches Prince Aldric as he stumbles, and they tumble onto solid ground as the bridge falls.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric"]
    },
    {
      "scene_number": 18,
      "caption": "Safe beyond the city walls, they watch the ruin burn.",
      "visual_description": "The party stands on a hill overlooking the ruined city, smoke rising against a red sunset, and Prince Aldric kneels in gratitude to his rescuers.",
      "characters": ["Captain Eira", "Lysander the Scholar", "Mara the Healer", "Prince Aldric"]
    }
  ]
}

